/* prog25_balanced_multitype.c
 *
 * Reimplementation of the original binary's behaviour:
 *   - reads the first command‑line argument (or an empty string if none)
 *   - checks that parentheses, brackets and braces are properly balanced
 *   - prints "BALANCED" or "UNBALANCED"
 *
 * The program does not depend on any external libraries beyond the C
 * standard library and compiles with a normal C compiler (C99 or later).
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    const char *input;
    size_t len, i;
    char *stack;
    size_t sp = 0;               /* stack pointer */
    int ok = 1;                  /* assume balanced */

    /* If no argument is given, treat the input as the empty string. */
    if (argc < 2) {
        input = "";
    } else {
        input = argv[1];
    }

    len = strlen(input);
    /* Allocate a stack large enough for the worst case (all chars are openings). */
    stack = (char *)malloc(len + 1);
    if (!stack) {
        perror("malloc");
        return 1;
    }

    for (i = 0; i < len && ok; ++i) {
        char c = input[i];
        switch (c) {
            case '(':
                stack[sp++] = ')';
                break;
            case '[':
                stack[sp++] = ']';
                break;
            case '{':
                stack[sp++] = '}';
                break;
            case ')':
            case ']':
            case '}':
                if (sp == 0 || stack[sp - 1] != c) {
                    ok = 0;               /* mismatch */
                } else {
                    --sp;                 /* pop */
                }
                break;
            default:
                /* all other characters are ignored */
                break;
        }
    }

    /* If we finished the loop but the stack is not empty, the string is unbalanced. */
    if (sp != 0) {
        ok = 0;
    }

    puts(ok ? "BALANCED" : "UNBALANCED");

    free(stack);
    return 0;
}
